#include <vector>
#include <string>
#include <sstream>

using namespace std;

class Solution {
    int n;
    vector<vector<int>> adj;
    vector<int> tin, tout;
    int timer;
    vector<int> up;
    vector<int> depth;
    int LOG;

    struct Fenwick {
        int size;
        vector<int> tree;
        Fenwick(int n) : size(n), tree(n + 1, 0) {}
        void add(int i, int delta) {
            for (++i; i <= size; i += i & -i) tree[i] ^= delta;
        }
        int query(int i) {
            int sum = 0;
            for (++i; i > 0; i -= i & -i) sum ^= tree[i];
            return sum;
        }
    };

    vector<Fenwick> bit;

    void dfs(int v, int p, int d, vector<int>& p_arr) {
        tin[v] = ++timer;
        depth[v] = d;
        up[v] = p;
        p_arr[timer] = v;
        for (int u : adj[v]) {
            if (u != p) {
                dfs(u, v, d + 1, p_arr);
            }
        }
        tout[v] = timer;
    }

public:
    vector<bool> palindromePath(int n, vector<vector<int>>& edges, string s, vector<string>& queries) {
        this->n = n;
        adj.assign(n, vector<int>());
        for (const auto& edge : edges) {
            adj[edge[0]].push_back(edge[1]);
            adj[edge[1]].push_back(edge[0]);
        }

        tin.resize(n);
        tout.resize(n);
        up.resize(n);
        depth.resize(n);
        timer = 0;

        vector<int> p_arr(n + 1);
        dfs(0, 0, 0, p_arr);

        bit.reserve(26, Fenwick(n + 1)); // We have 26 letters
        for (int i = 0; i < 26; ++i) {
            bit.emplace_back(n);
        }

        for (int i = 0; i < n; ++i) {
            bit[s[i] - 'a'].add(tin[i], 1 << (s[i] - 'a'));
        }

        // Binary lifting table for LCA
        int max_depth = 1;
        while ((1 << max_depth) <= n) max_depth++;
        vector<vector<int>> up_table(n, vector<int>(max_depth, 0));
        for (int i = 0; i < n; ++i) up_table[i][0] = up[i];
        for (int j = 1; j < max_depth; ++j) {
            for (int i = 0; i < n; ++i) {
                up_table[i][j] = up_table[up_table[i][j - 1]][j - 1];
            }
        }

        auto get_lca = [&](int u, int v) {
            if (depth[u] < depth[v]) swap(u, v);
            for (int j = max_depth - 1; j >= 0; --j) {
                if (depth[u] - (1 << j) >= depth[v]) {
                    u = up_table[u][j];
                }
            }
            if (u == v) return u;
            for (int j = max_depth - 1; j >= 0; --j) {
                if (up_table[u][j] != up_table[v][j]) {
                    u = up_table[u][j];
                    v = up_table[v][j];
                }
            }
            return up[u];
        };

        vector<bool> ans;
        for (const string& q_str : queries) {
            stringstream ss(q_str);
            string type;
            ss >> type;
            if (type == "update") {
                int u;
                char c;
                ss >> u >> c;
                char old_c = s[u];
                if (old_c != c) {
                    bit[old_c - 'a'].add(tin[u], 1 << (old_c - 'a'));
                    s[u] = c;
                    bit[c - 'a'].add(tin[u], 1 << (c - 'a'));
                }
            } else {
                int u, v;
                ss >> u >> v;
                int lca = get_lca(u, v);

                int mask = 0;
                // Since our queries are subtree queries, but path on tree from u to v can be broken into
                // subtrees when represented using heavy-light or similar, wait.
                // Wait, tin/tout allows us to query subtrees. But path between u and v is not a single subtree.
                // Actually, a path between u and v passes through LCA.
                // Using Fenwick on tin/tout directly works for subtree, but path u-v corresponds to nodes on path.
                // Since this is standard, path u-v can be queried using path-to-root queries if we use BIT on Euler tour with point updates and range queries, 
                // but here updates are point updates (update node u) and we need path query.
                // Point update and path query on trees can be done by:
                // BIT with range updates (or heavy-light / Euler tour with tin/tout).
                // Wait! A standard trick: 
                // Path from u to v: we can XOR values. If we maintain prefix XOR from root to each node,
                // then path XOR from u to v is prefix[u] ^ prefix[v] ^ s[lca] (or similar).
                // But we have point updates! A point update at node u changes the prefix XOR for the *entire subtree* of u!
                // Yes! If we change s[u] to c, it affects all nodes in the subtree of u.
                // Therefore, a point update on node u becomes a RANGE update on [tin[u], tout[u]] for the prefix XORs!
                // And a path query from u to v can be answered by querying the prefix XOR at u and at v, combining them with LCA.
                // Even simpler: path query from u to v can be viewed as point queries if we use a BIT for subtree updates and point queries!
                // Wait, point update on tree node u -> range update on [tin[u], tout[u]] in BIT.
                // Path query from u to v -> we need the XOR sum of characters on path u to v.
                // Character at node x is present in path u-v if x is on the path.
                // If we maintain for each character a BIT over tin[], where update at u is range update on [tin[u], tout[u]],
                // then query at node x (point query) will give how many times character c appears on path from root to x!
                // Then path from u to v query is just: count(u) ^ count(v) ^ count(lca) ^ (character at lca).
                // Let's verify:
                // Point update on node u: character changes, say from old_c to new_c.
                // This means node u's character changes. This affects any path containing node u.
                // If we use BIT to support RANGE UPDATE and POINT QUERY:
                // Update at u: range XOR on [tin[u], tout[u]] with `1 << (c - 'a') ^ 1 << (old_c - 'a')`.
                // Point query at node x: query BIT at tin[x] gives the total XOR sum of characters on the path from root to x!
                // Then path from u to v XOR sum = query(u) ^ query(v) ^ (character mask of lca).
                // Perfect! This reduces to:
                // BIT size n+1, supporting range XOR update and point XOR query.
                // Range update [L, R] with val: add val at L, add val at R+1.
                // Point query at x: prefix XOR query at tin[x].
            }
        }

        // Let's rewrite with the correct BIT structure (Range XOR Update, Point XOR Query)
        struct BIT_Range {
            int size;
            vector<int> tree;
            BIT_Range(int n) : size(n), tree(n + 1, 0) {}
            void add(int i, int val) {
                for (; i <= size; i += i & -i) tree[i] ^= val;
            }
            void range_add(int l, int r, int val) {
                add(l, val);
                add(r + 1, val);
            }
            int query(int i) {
                int sum = 0;
                for (; i > 0; i -= i & -i) sum ^= tree[i];
                return sum;
            }
        };

        vector<BIT_Range> bits(26, BIT_Range(n + 2));

        auto update_char = [&](int u, char old_c, char new_c) {
            int mask = (1 << (old_c - 'a')) ^ (1 << (new_c - 'a'));
            for (int i = 0; i < 26; ++i) {
                if ((mask >> i) & 1) {
                    bits[i].range_add(tin[u], tout[u], 1);
                }
            }
        };

        // Initialize bits
        for (int i = 0; i < n; ++i) {
            bits[s[i] - 'a'].range_add(tin[i], tout[i], 1);
        }

        for (const string& q_str : queries) {
            stringstream ss(q_str);
            string type;
            ss >> type;
            if (type == "update") {
                int u;
                char c;
                ss >> u >> c;
                if (s[u] != c) {
                    update_char(u, s[u], c);
                    s[u] = c;
                }
            } else {
                int u, v;
                ss >> u >> v;
                int lca = get_lca(u, v);

                int odd_count = 0;
                for (int i = 0; i < 26; ++i) {
                    int count = bits[i].query(tin[u]) ^ bits[i].query(tin[v]) ^ ((s[lca] - 'a' == i) ? 1 : 0);
                    if (count & 1) {
                        odd_count++;
                    }
                }
                ans.push_back(odd_count <= 1);
            }
        }

        return ans;
    }
};
